import re
import subprocess
import tempfile
from pathlib import Path

GXX = "D:/mingw64/bin/g++.exe"
SRC = """#include <cstdio>
int scale(int v, int factor) { return v; }
int main() {
    int unused_var = 42;
    int r = scale(1, 2);
    std::printf("%d\\n", r);
}
"""
WARN = re.compile(r"-W[a-z][a-z0-9-]*")


def build(extra):
    with tempfile.TemporaryDirectory() as td:
        Path(td, "main.cpp").write_text(SRC, encoding="utf-8")
        p = subprocess.run([GXX, "-std=c++17", "-O2"] + extra + ["main.cpp", "-o", "main.exe"],
                           cwd=td, capture_output=True, text=True, encoding="utf-8", errors="replace")
        return p.returncode, p.stderr


def cats(text, kind):
    out = {}
    for line in text.splitlines():
        if (" %s: " % kind) in line or line.startswith(kind + ":"):
            for m in WARN.findall(line):
                out[m] = out.get(m, 0) + 1
    return out


rc1, err1 = build(["-Wall", "-Wextra"])
c1 = cats(err1, "warning")
print("[编译1] -Wall -Wextra            返回码=%d 警告数=%d" % (rc1, sum(c1.values())))
print("[警告类别] %s" % " ".join("%s=%d" % (k, c1[k]) for k in sorted(c1)))

rc2, err2 = build(["-Wall", "-Wextra", "-Werror"])
c2 = cats(err2, "error")
print("[编译2] -Wall -Wextra -Werror    返回码=%d 错误数=%d" % (rc2, sum(c2.values())))
print("[升级为错误] %s" % " ".join("%s=%d" % (k, c2[k]) for k in sorted(c2)))
first = ""
for line in err2.splitlines():
    if " error: " in line:
        first = line.split(" error: ", 1)[1].split(" [", 1)[0]
        break
print("[首条诊断] %s" % first)
print("[判定] 无 -Werror 时构建成功=%s，加 -Werror 后构建失败=%s -> 告警即错误生效" % (rc1 == 0, rc2 != 0))
print("[同一份源码] 警告 %d 处，在 CI 上被 -Werror 拦下 1 次即中断整个流水线" % sum(c1.values()))
